async def list(self, provider: str | None = None, format: str | None = None) -> list[dict]:
def _list() -> list[dict]:
    entries = []
    for manifest_path in self._manifest_paths():
        manifest = json.loads(manifest_path.read_text())
        if provider is not None and manifest["provider"] != provider:
            continue
        if format is not None and manifest["format"] != format:
            continue
        # Handle legacy manifests missing size_bytes
        data_path = self._data_path(
            manifest.get("provider", ""),
            manifest.get("canonical_identifier", ""),
            manifest.get("format", "")
        )
        size_bytes = manifest.get("size_bytes")
        if size_bytes is None:
            try:
                size_bytes = data_path.stat().st_size
            except FileNotFoundError:
                size_bytes = 0

        entries.append(
            {
                "provider": manifest["provider"],
                "identifier": manifest.get("public_identifier") or manifest["canonical_identifier"],
                "format": manifest["format"],
                "fetched_at": manifest["fetched_at"],
                "size_bytes": size_bytes,
            }
        )
    return entries

return await to_thread.run_sync(_list)

def get_current_value(device_id: int, parameter_code: CompitParameter):
device = all_devices.get(device_id)
if not device:
    return None
code = PARAMS[parameter_code].get(device.definition.code, parameter_code.value)
param = next(
    (p for p in device.state.params if p.code == code),
    None,
)
return param.value if param else None
